using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using RaceDay.Mvc.Models;using RaceDay.Mvc.Services;
namespace RaceDay.Mvc.Controllers;
[Authorize(Roles="Organiser")]
public class OrganiserController(RaceDayApiClient api):Controller{
 public async Task<IActionResult> Index(){try{var all=await api.Get<List<EventDto>>("api/events")??new();var userId=int.Parse(User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value);return View(all.Where(e=>e.OrganiserId==userId).ToList());}catch(ApiException e){TempData["Error"]=e.Message;return View(new List<EventDto>());}}
 [HttpGet]public IActionResult Create()=>View("Edit",new EventVm());
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> Create(EventVm vm){if(!ModelState.IsValid)return View("Edit",vm);try{var ev=await api.Post<EventDto>("api/events",new{vm.EventName,vm.Description,EventDate=vm.EventDate,vm.Location,vm.DistanceKm,vm.EventType,vm.Status});if(vm.Banner!=null&&ev!=null)await api.Upload<object>($"api/events/{ev.EventId}/banner",vm.Banner);TempData["Success"]="Event created.";return RedirectToAction("Index");}catch(ApiException e){ModelState.AddModelError("",e.Message);return View("Edit",vm);}}
 [HttpGet]public async Task<IActionResult> Edit(int id){try{var e=await api.Get<EventDto>($"api/events/{id}");if(e==null||e.OrganiserId!=int.Parse(User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value))return NotFound();return View(new EventVm{EventId=id,EventName=e.EventName,Description=e.Description,EventDate=e.EventDate,Location=e.Location,DistanceKm=e.DistanceKm,EventType=e.EventType,Status=e.Status});}catch(ApiException e){TempData["Error"]=e.Message;return RedirectToAction("Index");}}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> Edit(EventVm vm){if(!ModelState.IsValid)return View(vm);try{await api.Put<EventDto>($"api/events/{vm.EventId}",new{vm.EventName,vm.Description,EventDate=vm.EventDate,vm.Location,vm.DistanceKm,vm.EventType,vm.Status});if(vm.Banner!=null)await api.Upload<object>($"api/events/{vm.EventId}/banner",vm.Banner);TempData["Success"]="Event updated.";return RedirectToAction("Index");}catch(ApiException e){ModelState.AddModelError("",e.Message);return View(vm);}}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> Delete(int id){try{await api.Delete<object>($"api/events/{id}");TempData["Success"]="Event deleted.";}catch(ApiException e){TempData["Error"]=e.Message;}return RedirectToAction("Index");}
 [HttpGet]public async Task<IActionResult> Categories(int id){try{ViewBag.Event=await api.Get<EventDto>($"api/events/{id}");ViewBag.EventId=id;return View(await api.Get<List<CategoryDto>>($"api/events/{id}/categories")??new());}catch(ApiException e){TempData["Error"]=e.Message;return RedirectToAction("Index");}}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> AddCategory(CategoryVm vm){try{await api.Post<CategoryDto>($"api/events/{vm.EventId}/categories",vm);TempData["Success"]="Category added.";}catch(ApiException e){TempData["Error"]=e.Message;}return RedirectToAction("Categories",new{id=vm.EventId});}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> DeleteCategory(int id,int eventId){try{await api.Delete<object>($"api/categories/{id}");TempData["Success"]="Category removed.";}catch(ApiException e){TempData["Error"]=e.Message;}return RedirectToAction("Categories",new{id=eventId});}
 [HttpGet]public async Task<IActionResult> Enrolments(int id){try{ViewBag.Event=await api.Get<EventDto>($"api/events/{id}");ViewBag.EventId=id;ViewBag.Results=await api.Get<List<ResultDto>>($"api/events/{id}/results")??new();return View(await api.Get<List<EnrolmentDto>>($"api/events/{id}/enrolments")??new());}catch(ApiException e){TempData["Error"]=e.Message;return RedirectToAction("Index");}}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> RecordResult(ResultVm vm){try{await api.Post<ResultDto>($"api/enrolments/{vm.EnrolmentId}/result",new{vm.Status,vm.FinishTime,vm.Position});TempData["Success"]="Result recorded.";}catch(ApiException e){TempData["Error"]=e.Message;}return RedirectToAction("Index");}
 [HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> UpdateResult(int id,ResultVm vm){try{await api.Put<ResultDto>($"api/results/{id}",new{vm.Status,vm.FinishTime,vm.Position});TempData["Success"]="Result updated.";}catch(ApiException e){TempData["Error"]=e.Message;}return RedirectToAction("Index");}
}